from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe')
base='3435b774e13a692443215349e04e176823871598'
def git(*a):return subprocess.run(['git',*a],cwd=repo,capture_output=True,text=True,check=True).stdout.strip()
if git('rev-parse','HEAD')!=base or git('rev-parse','origin/main')!=base:raise SystemExit('AUTHORITY_CHANGED')
src=repo/'tools/ats_review_smoke.py'; test=repo/'tests/test_ats_review_smoke.py'
if git('status','--porcelain','--','tools/ats_review_smoke.py','tests/test_ats_review_smoke.py'):raise SystemExit('TARGET_DIRTY')
if test.exists():raise SystemExit('TEST_PATH_EXISTS')
s=src.read_text()
# Critical smoke-gate flaw: pytest return code 0 also covers all-skipped browser tests.
# Enforce the four ATS Review cases actually executed, not a green result from browser skips.
s=s.replace('import subprocess\n','import subprocess\nimport re\n',1)
s=s.replace('''    proc = subprocess.Popen(command, cwd=ROOT, start_new_session=True)
    try:
        rc = proc.wait(timeout=300)''','''    proc = subprocess.Popen(command, cwd=ROOT, start_new_session=True,
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    try:
        output, _ = proc.communicate(timeout=300)
        rc = proc.returncode''',1)
s=s.replace('''            proc.wait(timeout=8)''','''            proc.communicate(timeout=8)''',1)
s=s.replace('''            proc.wait()
        print("ATS_FIXTURE''','''            proc.communicate()
        print("ATS_FIXTURE''',1)
old='''    print(f"ATS_FIXTURE_REVIEW_GATE={'PASS' if rc == 0 else 'FAIL'}; LIVE_REVIEW=NOT_VERIFIED; SUBMISSIONS=NOT_ATTEMPTED", flush=True)
    return rc'''
new='''    print(output, end="" if output.endswith("\\n") else "\\n", flush=True)
    match = re.search(r"(?<!\\d)(\\d+) passed", output)
    count = int(match.group(1)) if match else 0
    # At least four distinct adapter Review fixtures + five safety assertions;
    # skips are disallowed because Chromium may be missing.
    good = rc == 0 and count >= 9 and not re.search(r"\\d+ skipped", output)
    print(f"ATS_FIXTURE_REVIEW_GATE={'PASS' if good else 'FAIL'}; LIVE_REVIEW=NOT_VERIFIED; SUBMISSIONS=NOT_ATTEMPTED", flush=True)
    return 0 if good else (rc or 1)'''
if s.count(old)!=1:raise SystemExit('SOURCE_CHANGED')
src.write_text(s.replace(old,new,1))
test.write_text('''"""Smoke-gate result must fail closed when Chromium fixture tests are skipped."""
from tools import ats_review_smoke

def test_smoke_success_requires_executed_tests(monkeypatch):
    class FakeProcess:
        def __init__(self, output, code):
            self.output, self.returncode = output, code
        def communicate(self, timeout=None):
            return self.output, None
    def mock_popen(*args, **kwargs):
        return FakeProcess("9 passed in 1.0s", 0)
    monkeypatch.setattr(ats_review_smoke.subprocess, "Popen", mock_popen)
    assert ats_review_smoke.main() == 0

def test_smoke_refuses_green_all_skipped(monkeypatch):
    class FakeProcess:
        returncode = 0
        def communicate(self, timeout=None):
            return "9 skipped in 1.0s", None
    monkeypatch.setattr(ats_review_smoke.subprocess, "Popen",
                        lambda *a, **k: FakeProcess())
    assert ats_review_smoke.main() != 0

def test_smoke_refuses_partial_and_failed_runs(monkeypatch):
    class FakeProcess:
        returncode = 0
        def communicate(self, timeout=None):
            return "4 passed, 5 skipped in 1.0s", None
    monkeypatch.setattr(ats_review_smoke.subprocess, "Popen",
                        lambda *a, **k: FakeProcess())
    assert ats_review_smoke.main() != 0
''')
def run(args,seconds):
 p=subprocess.Popen(args,cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=seconds)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('TIMEOUT',o[-2500:],flush=True);raise SystemExit(124)
 print('RESULT',p.returncode,o[-3800:],e[-700:],flush=True)
 return p.returncode,o
rc,_=run([str(repo/'.venv/bin/python'),'-m','pytest','-q','tests/test_ats_review_smoke.py'],90)
if rc:raise SystemExit('GATE_UNIT_FAILED')
rc,out=run([str(repo/'.venv/bin/python'),'tools/ats_review_smoke.py'],380)
if rc or 'ATS_FIXTURE_REVIEW_GATE=PASS' not in out:raise SystemExit('SMOKE_FAILED')
subprocess.run(['git','add','--','tools/ats_review_smoke.py','tests/test_ats_review_smoke.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','fix: fail closed when ATS Review smoke browser fixtures are skipped'],cwd=repo,check=True)
